import { createElement } from '../../vendor/react.js';

// Action controls will expand (export, share, save).
export function Toolbar() {
  return createElement(
    'nav',
    { className: 'toolbar' },
    createElement('span', { className: 'doc-title' }, 'Untitled'),
    createElement('button', { type: 'button', className: 'ghost' }, 'Cancel'),
  );
}

import { createElement } from '../../vendor/react.js';
import { classNames } from '../../lib/classNames.js';

export function Pressable({
  variant = 'secondary',
  disabled = false,
  children = '',
} = {}) {
  const kind = variant === 'primary' ? 'primary' : 'secondary';
  return createElement(
    'button',
    {
      type: 'button',
      className: classNames('btn', `btn-${kind}`),
      disabled: Boolean(disabled),
    },
    children,
  );
}

import { createElement } from '../../vendor/react.js';

export function LoadingSpinner() {
  return createElement('span', { className: 'spinner', 'aria-hidden': 'true' });
}

export function useBusyState(initial = false) {
  let busy = Boolean(initial);
  return {
    get busy() {
      return busy;
    },
    start() {
      busy = true;
    },
    stop() {
      busy = false;
    },
  };
}

